import sys

def maximize_duels(n):
    board = []
    for i in range(n):
        row = []
        for j in range(n):
            if (i + j) % 2 == 0:
                row.append('W')
            else:
                row.append('B')
        board.append(''.join(row))
    return board

def main():
    n = int(sys.stdin.read().strip())
    result = maximize_duels(n)
    for row in result:
        print(row)

if __name__ == "__main__":
    main()
